import {forward} from './vendor/mgrs.js';
export const precisionForZoom=percent=>Math.max(1,Math.min(5,1+Math.floor(Math.max(0,Math.min(100,percent))/20)));
export function mgrsReference(longitude,latitude,precision=3){if(latitude< -80||latitude>84)return null;try{const raw=forward([((longitude+180)%360+360)%360-180,latitude],precision),match=raw.match(/^(\d{1,2}[C-X])([A-Z]{2})(\d+)$/);if(!match)return raw;return `${match[1]} ${match[2]} ${match[3].slice(0,precision)} ${match[3].slice(precision)}`;}catch{return null;}}
export function gridZones(){const result=[];for(let band=0;band<20;band++){const south=-80+band*8,north=band===19?84:south+8;for(let zone=1;zone<=60;zone++){let west=(zone-1)*6-180,east=west+6;if(band===17){if(zone===31)east=3;if(zone===32)west=3;}if(band===19){if([32,34,36].includes(zone))continue;if(zone===31)east=9;if(zone===33){west=9;east=21;}if(zone===35){west=21;east=33;}if(zone===37)west=33;}result.push({zone,band,west,east,south,north});}}return result;}

// MGRS components need their grid-zone and 100 km square context when an axis crosses zones.
export function mgrsAxisLabels({width,height,unproject,precision}){const labels=[],bottom=unproject(width/2,height-157);let axisY=height-157;if(bottom.y< -80){const top=unproject(width/2,0),scale=height/(top.y-unproject(width/2,height).y);axisY=Math.min(axisY,(top.y+79.99999)*scale);}axisY=Math.max(150,Math.min(height-157,axisY));const add=(axis,x,y)=>{const point=unproject(axis==='x'?x:0,axis==='y'?y:axisY),reference=mgrsReference(point.x,point.y,precision);if(!reference)return;const [zone,square,easting,northing]=reference.split(' ');labels.push({axis,x,y,zone,square,value:axis==='x'?easting:northing,reference,longitude:point.x,latitude:point.y});};for(let x=90;x<width-30;x+=150)add('x',x,axisY);for(let y=195;y<height-180;y+=100)add('y',5,y);return labels;}
